{
  "typography": {
    "caption": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "title": {
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 44
      },
      "density": {
        "pointer": {
          "pad": 12,
          "gap": 8
        },
        "touch": {
          "pad": 12,
          "gap": 8
        }
      },
      "item": {
        "pointer": {
          "inset": 4,
          "pad": 11
        },
        "touch": {
          "inset": 4,
          "pad": 11
        }
      },
      "control": {
        "pointer": {
          "padding": 6,
          "gap": 8
        },
        "touch": {
          "padding": 6,
          "gap": 8
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 32,
          "lg": 40
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "double",
      "width": 2,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "controls": {
    "button": {
      "corner": {
        "sm": "control",
        "md": "control",
        "lg": "control"
      },
      "selected": {
        "face": {
          "finish": "accent"
        },
        "ink": {
          "color": "primary-foreground"
        }
      },
      "secondary": {
        "face": {
          "finish": "raised"
        },
        "ink": {
          "color": "foreground"
        },
        "edge": {
          "finish": "raised",
          "field": "borderColor"
        },
        "hover": {
          "finish": "hover"
        }
      },
      "outline": {
        "edge": {
          "finish": "raised",
          "field": "borderColor"
        }
      },
      "destructive": {
        "edge": "none"
      },
      "shade": "raised"
    },
    "badge": {
      "corner": "control"
    },
    "field": {
      "edge": {
        "sides": true,
        "color": {
          "color": "line"
        },
        "bottom": {
          "color": "input"
        }
      },
      "corner": {
        "bottom": "control"
      },
      "focus": {
        "line": true,
        "width": 2,
        "color": {
          "color": "brand"
        }
      },
      "disabled": {
        "face": {
          "finish": "disabled"
        }
      }
    },
    "choice": {
      "size": {
        "pointer": 20,
        "touch": 20
      },
      "box": {
        "pointer": 20,
        "touch": 20
      },
      "corner": {
        "pointer": 4,
        "touch": 4
      },
      "face": {
        "color": "track"
      },
      "shade": "none",
      "edge": {
        "width": 1,
        "color": {
          "color": "input"
        },
        "disabled": {
          "color": "input"
        }
      },
      "checked": {
        "face": {
          "color": "primary"
        }
      },
      "radio": {
        "checked": {
          "face": {
            "color": "primary"
          },
          "edge": "none"
        }
      },
      "mark": {
        "size": {
          "pointer": 12,
          "touch": 12
        },
        "hover": 14,
        "pressed": 10
      },
      "halo": "none"
    },
    "switch": {
      "track": {
        "pointer": [
          40,
          20
        ],
        "touch": [
          44,
          22
        ]
      },
      "small": {
        "track": {
          "pointer": [
            32,
            16
          ],
          "touch": [
            36,
            18
          ]
        },
        "knob": {
          "pointer": 10,
          "touch": 12
        }
      },
      "edge": {
        "off": 1,
        "on": 0,
        "color": {
          "color": "input"
        }
      },
      "knob": {
        "size": {
          "pointer": 12,
          "touch": 14
        },
        "on": "same",
        "hover": {
          "pointer": 14,
          "touch": 16
        },
        "pressed": {
          "pointer": [
            17,
            14
          ],
          "touch": [
            19,
            16
          ]
        }
      }
    },
    "slider": {
      "rail": {
        "pointer": 4,
        "touch": 6
      },
      "band": {
        "pointer": 32,
        "touch": 36
      },
      "face": {
        "color": "input"
      },
      "shade": "none",
      "edge": {
        "color": "none",
        "width": 0
      },
      "knob": {
        "size": {
          "pointer": 18,
          "touch": 24
        },
        "pressed": {
          "pointer": 18,
          "touch": 36
        },
        "face": {
          "finish": "knob"
        },
        "edge": "none"
      },
      "mark": {
        "size": 12,
        "hover": 14,
        "pressed": 10
      },
      "brightens": false
    },
    "progress": {
      "height": 3,
      "line": 1,
      "face": {
        "color": "input"
      },
      "shade": "none",
      "edge": {
        "color": "none",
        "width": 0
      }
    },
    "calendar": {
      "today": {
        "face": {
          "color": "foreground",
          "alpha": 0.08
        },
        "ink": {
          "color": "foreground"
        }
      }
    },
    "spinner": {
      "opacity": 0,
      "spokes": false
    },
    "popup": {
      "corner": "container"
    },
    "tooltip": {
      "face": {
        "finish": "inverse"
      },
      "ink": {
        "finish": "inverse",
        "field": "foreground"
      },
      "edge": {
        "finish": "inverse",
        "field": "borderColor"
      },
      "shade": "inverse"
    },
    "toast": {
      "action": {
        "face": {
          "finish": "accent"
        }
      }
    },
    "list": {
      "item": {
        "highlight": {
          "color": "accent"
        },
        "edge": "none"
      }
    },
    "menubar": {
      "bar": "none"
    },
    "tabs": {
      "track": {
        "face": {
          "color": "inset"
        },
        "edge": {
          "color": "line"
        },
        "corner": "control"
      }
    },
    "well": {
      "edge": {
        "color": "border"
      }
    },
    "disabled": {
      "face": {
        "finish": "disabled"
      },
      "ink": {
        "finish": "disabled",
        "field": "foreground"
      },
      "edge": {
        "finish": "disabled",
        "field": "borderColor"
      }
    }
  },
  "shape": {
    "curve": "circular"
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0,
      "pressed": 0
    },
    "pressed-opacity": 1,
    "rest-opacity": 0.5,
    "disabled": {
      "content": 0.36
    }
  },
  "motion": {
    "fast": {
      "duration": 83,
      "timingFunction": "decelerate"
    },
    "default": {
      "duration": 167,
      "timingFunction": "decelerate"
    },
    "slow": {
      "duration": 250,
      "timingFunction": "decelerate"
    },
    "state": {
      "duration": 83,
      "timingFunction": "decelerate"
    }
  },
  "finishes": {
    "shared": {
      "card": {
        "background": "{card}",
        "shadow": "none",
        "foreground": "{foreground}",
        "elevation": null
      },
      "inset": {
        "shadow": "none",
        "foreground": "{foreground}"
      },
      "channel": {
        "background": "{inset}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{line}"
      },
      "raised": {
        "background": "{raised}",
        "shadow": "none",
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": null
      },
      "plate": {
        "background": "{card}",
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "transparent",
        "elevation": null
      },
      "overlay": {
        "foreground": "{foreground}",
        "backdropFilter": "none",
        "material": "acrylic",
        "elevation": null
      },
      "modal": {
        "background": "{background}",
        "foreground": "{foreground}",
        "border-color": "oklch(0.5624 0 0 / 0.4)",
        "elevation": null
      },
      "inverse": {
        "background": "{inverse}",
        "foreground": "{inverse-foreground}",
        "border-color": "{line}",
        "backdropFilter": "none",
        "material": null,
        "elevation": null
      },
      "glass": {
        "shadow": "none",
        "foreground": "{foreground}",
        "border-color": "{line}",
        "backdropFilter": "blur(30px)",
        "material": null,
        "elevation": null
      },
      "accent": {
        "background": "{primary}",
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "border-bottom-color": "{brand-edge}",
        "pressed-opacity": 1
      },
      "fill": {
        "shadow": "none",
        "foreground": "{primary-foreground}",
        "background": "{primary}",
        "gradient": null
      },
      "knob": {
        "shadow": "none",
        "foreground": "{foreground}",
        "background": "{knob}",
        "gradient": null,
        "border-color": "transparent",
        "checked-background": "{primary-foreground}"
      },
      "hover": {
        "shadow": "none",
        "foreground": "{foreground}",
        "background": "{hover}",
        "elevation": null
      },
      "pressed": {
        "shadow": "none",
        "foreground": "{muted-foreground}",
        "background": "{muted}",
        "border-color": "{line}",
        "elevation": null
      },
      "disabled": {
        "shadow": "none"
      }
    },
    "light": {
      "card": {
        "border-color": "oklch(0 0 0 / 0.059)"
      },
      "inset": {
        "border-color": "oklch(0 0 0 / 0.059)",
        "border-bottom-color": "oklch(0 0 0 / 0.447)"
      },
      "raised": {
        "border-color": "oklch(0 0 0 / 0.059)",
        "border-top-color": "oklch(0 0 0 / 0.059)",
        "border-bottom-color": "oklch(0 0 0 / 0.161)"
      },
      "overlay": {
        "background": "oklch(from {popover} l c h / 0.85)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.12), 0 16px 32px oklch(0 0 0 / 0.14)",
        "border-color": "oklch(0 0 0 / 0.059)"
      },
      "modal": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.12), 0 64px 128px oklch(0 0 0 / 0.14)"
      },
      "inverse": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.12), 0 4px 8px oklch(0 0 0 / 0.14)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.85)"
      },
      "accent": {
        "border-color": "oklch(0.52768 0.14982 252.341)",
        "pressed-background": "oklch(0.5773 0.13223 250.006)",
        "pressed-foreground": "oklch(0.87245 0.03754 247.003)"
      },
      "fill": {
        "border-color": "oklch(0.52768 0.14982 252.341)"
      },
      "hover": {
        "border-color": "oklch(0 0 0 / 0.059)",
        "border-top-color": "oklch(0 0 0 / 0.059)",
        "border-bottom-color": "oklch(0 0 0 / 0.161)"
      },
      "disabled": {
        "background": "oklch(0.97015 0 0)",
        "foreground": "oklch(0.68949 0 0)",
        "border-color": "oklch(0 0 0 / 0.059)"
      }
    },
    "dark": {
      "card": {
        "border-color": "oklch(0 0 0 / 0.102)"
      },
      "inset": {
        "border-color": "oklch(1 0 0 / 0.071)",
        "border-bottom-color": "oklch(1 0 0 / 0.545)"
      },
      "raised": {
        "border-color": "oklch(1 0 0 / 0.071)",
        "border-top-color": "oklch(1 0 0 / 0.094)",
        "border-bottom-color": "oklch(1 0 0 / 0.071)"
      },
      "overlay": {
        "background": "oklch(from {popover} l c h / 0.96)",
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)",
        "border-color": "oklch(0 0 0 / 0.2)"
      },
      "modal": {
        "shadow": "0 0 8px oklch(0 0 0 / 0.4), 0 64px 128px oklch(0 0 0 / 0.48)"
      },
      "inverse": {
        "shadow": "0 0 2px oklch(0 0 0 / 0.24), 0 4px 8px oklch(0 0 0 / 0.28)"
      },
      "glass": {
        "background": "oklch(from {popover} l c h / 0.96)"
      },
      "accent": {
        "border-color": "oklch(0.81732 0.11439 230)",
        "pressed-background": "oklch(0.70029 0.10192 230.522)",
        "pressed-foreground": "oklch(0.42706 0.05878 229.834)"
      },
      "fill": {
        "border-color": "oklch(0.81732 0.11439 230)"
      },
      "hover": {
        "border-color": "oklch(1 0 0 / 0.071)",
        "border-top-color": "oklch(1 0 0 / 0.094)",
        "border-bottom-color": "oklch(1 0 0 / 0.071)"
      },
      "disabled": {
        "background": "oklch(0.28502 0 0)",
        "foreground": "oklch(0.54863 0 0)",
        "border-color": "oklch(1 0 0 / 0.071)"
      }
    }
  },
  "elevation": {
    "light": {
      "sm": null,
      "md": "0 0 2px oklch(0 0 0 / 0.12), 0 4px 8px oklch(0 0 0 / 0.14)",
      "lg": "0 0 8px oklch(0 0 0 / 0.12), 0 16px 32px oklch(0 0 0 / 0.14)",
      "xl": "0 0 8px oklch(0 0 0 / 0.12), 0 64px 128px oklch(0 0 0 / 0.14)",
      "inset": null
    },
    "dark": {
      "sm": null,
      "md": "0 0 2px oklch(0 0 0 / 0.24), 0 4px 8px oklch(0 0 0 / 0.28)",
      "lg": "0 0 8px oklch(0 0 0 / 0.4), 0 16px 32px oklch(0 0 0 / 0.48)",
      "xl": "0 0 8px oklch(0 0 0 / 0.4), 0 64px 128px oklch(0 0 0 / 0.48)",
      "inset": null
